const sales = $('PostgreSQL - Extract Sales Data').all();
const payments = $('Stripe - Extract Payment Data').all();
const crm = $('CRM API - Extract Customer Data').all();

const merged = sales.map(sale => {
  const payment = payments.find(p => p.json.metadata?.order_id === sale.json.id);
  const customer = crm.find(c => c.json.id === sale.json.customer_id);
  return {
    json: {
      order_id: sale.json.id,
      customer_id: sale.json.customer_id,
      customer_segment: customer?.json.segment || 'unknown',
      amount: sale.json.total_amount,
      payment_method: payment?.json.payment_method_details?.type || 'unknown',
      created_at: sale.json.created_at
    }
  };
});

return merged;
